class ReturnSale(Wizard):
    __name__ = 'sale.return_sale'
    start = StateView('sale.return_sale.start',
        'sale.return_sale_start_view_form', [
            Button('Cancel', 'end', 'tryton-cancel'),
            Button('Return', 'return_', 'tryton-ok', default=True),
            ])
    return_ = StateAction('sale.act_sale_form')

    def do_return_(self, action):
        sales = self.records
        return_sales = self.model.copy(sales, default={
                'origin': lambda data: (
                    '%s,%s' % (self.model.__name__, data['id'])),
                'lines.quantity': lambda data: (
                    data['quantity'] * -1 if data['type'] == 'line'
                    else data['quantity']),
                })

        data = {'res_id': [s.id for s in return_sales]}
        if len(return_sales) == 1:
            action['views'].reverse()
        return action, data

@Override
@Transactional(rollbackOn = {Exception.class})
public void cancelSaleOrder(
    SaleOrder saleOrder, CancelReason cancelReason, String cancelReasonStr)
    throws AxelorException {

  List<Integer> authorizedStatus = new ArrayList<>();
  authorizedStatus.add(SaleOrderRepository.STATUS_DRAFT_QUOTATION);
  authorizedStatus.add(SaleOrderRepository.STATUS_FINALIZED_QUOTATION);
  if (saleOrder.getStatusSelect() == null
      || !authorizedStatus.contains(saleOrder.getStatusSelect())) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SaleExceptionMessage.SALE_ORDER_CANCEL_WRONG_STATUS));
  }

  Query q =
      JPA.em()
          .createQuery(
              "select count(*) FROM SaleOrder as self WHERE self.statusSelect in (?1 , ?2) AND self.clientPartner = ?3 ");
  q.setParameter(1, SaleOrderRepository.STATUS_ORDER_CONFIRMED);
  q.setParameter(2, SaleOrderRepository.STATUS_ORDER_COMPLETED);
  q.setParameter(3, saleOrder.getClientPartner());
  if ((long) q.getSingleResult() == 0) {
    saleOrder.getClientPartner().setIsCustomer(false);
    saleOrder.getClientPartner().setIsProspect(true);
  }
  saleOrder.setStatusSelect(SaleOrderRepository.STATUS_CANCELED);
  saleOrder.setCancelReason(cancelReason);
  if (Strings.isNullOrEmpty(cancelReasonStr)) {
    saleOrder.setCancelReasonStr(cancelReason.getName());
  } else {
    saleOrder.setCancelReasonStr(cancelReasonStr);
  }
  saleOrderRepo.save(saleOrder);
}

@Transactional(rollbackOn = {Exception.class})
public void completeSaleOrder(SaleOrder saleOrder) throws AxelorException {

  if (saleOrder.getStatusSelect() == null
      || saleOrder.getStatusSelect() != SaleOrderRepository.STATUS_ORDER_CONFIRMED) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(SaleExceptionMessage.SALE_ORDER_COMPLETE_WRONG_STATUS));
  }

  saleOrder.setStatusSelect(SaleOrderRepository.STATUS_ORDER_COMPLETED);
  saleOrder.setOrderBeingEdited(false);

  saleOrderRepo.save(saleOrder);

@Override
@Transactional(rollbackOn = {Exception.class})
public void validatePurchaseOrder(PurchaseOrder purchaseOrder) throws AxelorException {

  if (purchaseOrder.getStatusSelect() == null
      || purchaseOrder.getStatusSelect() != PurchaseOrderRepository.STATUS_REQUESTED) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(PurchaseExceptionMessage.PURCHASE_ORDER_VALIDATE_WRONG_STATUS));
  }

  purchaseOrderService.computePurchaseOrder(purchaseOrder);

  purchaseOrder.setStatusSelect(PurchaseOrderRepository.STATUS_VALIDATED);
  purchaseOrder.setValidationDateTime(
      appPurchaseService.getTodayDateTime(purchaseOrder.getCompany()).toLocalDateTime());
  purchaseOrder.setValidatedByUser(AuthUtils.getUser());

  purchaseOrder.setSupplierPartner(purchaseOrderService.validateSupplier(purchaseOrder));
  purchaseOrderTypeSelectService.setTypeSelect(purchaseOrder);

  purchaseOrderService.updateCostPrice(purchaseOrder);
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void finishPurchaseOrder(PurchaseOrder purchaseOrder) throws AxelorException {

  if (purchaseOrder.getStatusSelect() == null
      || purchaseOrder.getStatusSelect() != PurchaseOrderRepository.STATUS_VALIDATED) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(PurchaseExceptionMessage.PURCHASE_ORDER_FINISH_WRONG_STATUS));
  }

  purchaseOrder.setStatusSelect(PurchaseOrderRepository.STATUS_FINISHED);
  purchaseOrderRepo.save(purchaseOrder);
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void cancelPurchaseOrder(PurchaseOrder purchaseOrder) throws AxelorException {
  List<Integer> authorizedStatus = new ArrayList<>();
  authorizedStatus.add(PurchaseOrderRepository.STATUS_DRAFT);
  authorizedStatus.add(PurchaseOrderRepository.STATUS_REQUESTED);
  authorizedStatus.add(PurchaseOrderRepository.STATUS_VALIDATED);
  if (purchaseOrder.getStatusSelect() == null
      || !authorizedStatus.contains(purchaseOrder.getStatusSelect())) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(PurchaseExceptionMessage.PURCHASE_ORDER_CANCEL_WRONG_STATUS));
  }

  purchaseOrder.setStatusSelect(PurchaseOrderRepository.STATUS_CANCELED);
  purchaseOrderRepo.save(purchaseOrder);

